    sfu_basketball_11_21/frame_aligned_videos/downscaled/448 \
    sfu_basketball_11_21/trajectory/gopro_calibs.csv \
    sfu_basketball_11_29/frame_aligned_videos/cam01.mp4 \
    sfu_basketball_11_29/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_11_29/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_11_29/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_11_29/frame_aligned_videos/downscaled/448 \
    sfu_basketball_11_29/trajectory/gopro_calibs.csv \
    sfu_basketball_11_31/frame_aligned_videos/cam01.mp4 \
    sfu_basketball_11_31/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_11_31/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_11_31/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_11_31/frame_aligned_videos/downscaled/448 \
